import{_ as d,o as r,c as o,a3 as a}from"./chunks/framework.B9qR_F1m.js";const q=JSON.parse('{"title":"文言实词与虚词","description":"按卡片形式整理高频文言实词的义项与例句、18 个常见虚词的用法，并归纳四类特殊句式与翻译顺序。","frontmatter":{"title":"文言实词与虚词","date":"2026-10-18T00:00:00.000Z","subject":"chinese","subjectLabel":"语文","category":"古代文学","tags":["文言实词","文言虚词","文言句式"],"description":"按卡片形式整理高频文言实词的义项与例句、18 个常见虚词的用法，并归纳四类特殊句式与翻译顺序。"},"headers":[],"relativePath":"subjects/chinese/classical/classical-words.md","filePath":"subjects/chinese/classical/classical-words.md","lastUpdated":null}'),s={name:"subjects/chinese/classical/classical-words.md"};function n(e,t,l,i,h,g){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="文言实词与虚词" tabindex="-1">文言实词与虚词 <a class="header-anchor" href="#文言实词与虚词" aria-label="Permalink to &quot;文言实词与虚词&quot;">​</a></h1><blockquote><p><strong>一句话概括</strong>：文言阅读的障碍 80% 集中在&quot;熟词生义&quot;和&quot;虚词辨义&quot;上，两者都需要按义项记忆而非按字记忆。</p></blockquote><h2 id="一、实词记忆法" tabindex="-1">一、实词记忆法 <a class="header-anchor" href="#一、实词记忆法" aria-label="Permalink to &quot;一、实词记忆法&quot;">​</a></h2><h3 id="三条原则" tabindex="-1">三条原则 <a class="header-anchor" href="#三条原则" aria-label="Permalink to &quot;三条原则&quot;">​</a></h3><ol><li><strong>以本义带引申义</strong>：先记住本义，再顺着&quot;由具体到抽象&quot;的链条推引申义；</li><li><strong>一个义项配一个原句</strong>：脱离句子的义项记不住，必须绑定语境；</li><li><strong>古今异义单独标注</strong>：双音节词在文言中常是两个单音节词，如&quot;妻子&quot;指&quot;妻子和儿女&quot;。</li></ol><h3 id="高频实词义项卡" tabindex="-1">高频实词义项卡 <a class="header-anchor" href="#高频实词义项卡" aria-label="Permalink to &quot;高频实词义项卡&quot;">​</a></h3><table tabindex="0"><thead><tr><th>词</th><th>本义</th><th>常见引申义</th><th>例句</th></tr></thead><tbody><tr><td>兵</td><td>兵器</td><td>士兵、军队、战争、战略</td><td>「收天下之<strong>兵</strong>，聚之咸阳」——兵器</td></tr><tr><td>病</td><td>重病</td><td>担心、困苦、指责</td><td>「君子<strong>病</strong>无能焉」——担心</td></tr><tr><td>乘</td><td>登、升</td><td>驾车、趁机、量词（四马一车）</td><td>「<strong>乘</strong>彼垝垣」——登上</td></tr><tr><td>从</td><td>跟随</td><td>顺从、参与、由、堂房亲属</td><td>「<strong>从</strong>此道至吾军」——由、自</td></tr><tr><td>道</td><td>道路</td><td>方法、道义、说、取道</td><td>「师者，所以传<strong>道</strong>受业解惑也」——道理</td></tr><tr><td>顾</td><td>回头看</td><td>看望、考虑、但、反而</td><td>「<strong>顾</strong>不如蜀鄙之僧哉」——反而</td></tr><tr><td>举</td><td>举起</td><td>推荐、发动、全、攻克</td><td>「<strong>举</strong>孝廉不行」——被推荐</td></tr><tr><td>绝</td><td>断绝</td><td>横渡、极、停止、与世隔绝</td><td>「非能水也，而<strong>绝</strong>江河」——横渡</td></tr><tr><td>间</td><td>缝隙</td><td>参与、秘密地、隔阂、间或</td><td>「又何<strong>间</strong>焉」——参与</td></tr><tr><td>信</td><td>言语真实</td><td>信用、确实、使者、随意</td><td>「<strong>信</strong>可乐也」——确实</td></tr></tbody></table><h3 id="词类活用辨识" tabindex="-1">词类活用辨识 <a class="header-anchor" href="#词类活用辨识" aria-label="Permalink to &quot;词类活用辨识&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>辨识方法</th><th>例句</th></tr></thead><tbody><tr><td>名词作动词</td><td>名词前有副词或后带宾语</td><td>「左右欲<strong>刃</strong>相如」——用刀杀</td></tr><tr><td>使动用法</td><td>动词/形容词后接宾语，意为&quot;使宾语怎样&quot;</td><td>「项伯杀人，臣<strong>活</strong>之」——使他活</td></tr><tr><td>意动用法</td><td>形容词/名词后接宾语，意为&quot;认为宾语怎样&quot;</td><td>「吾妻之<strong>美</strong>我者」——认为我美</td></tr><tr><td>名词作状语</td><td>名词直接修饰动词，表比喻、工具、处所</td><td>「<strong>犬</strong>坐于前」——像狗一样坐着</td></tr></tbody></table><h2 id="二、18-个常见虚词" tabindex="-1">二、18 个常见虚词 <a class="header-anchor" href="#二、18-个常见虚词" aria-label="Permalink to &quot;二、18 个常见虚词&quot;">​</a></h2><table tabindex="0"><thead><tr><th>虚词</th><th>主要用法</th><th>例句</th></tr></thead><tbody><tr><td>而</td><td>并列、承接、转折、修饰、假设</td><td>「蟹六跪<strong>而</strong>二螯」——并列</td></tr><tr><td>何</td><td>疑问代词、副词（多么）</td><td>「<strong>何</strong>陋之有」——什么</td></tr><tr><td>乎</td><td>疑问语气、介词（相当于&quot;于&quot;）、形容词词尾</td><td>「其闻道也固先<strong>乎</strong>吾」——比</td></tr><tr><td>乃</td><td>于是、才、竟、是、你的</td><td>「<strong>乃</strong>不知有汉」——竟然</td></tr><tr><td>其</td><td>代词、副词（大概/难道）、连词（如果）</td><td>「<strong>其</strong>孰能讥之乎」——难道</td></tr><tr><td>且</td><td>而且、况且、将要、暂且</td><td>「<strong>且</strong>焉置土石」——况且</td></tr><tr><td>若</td><td>像、如果、你（们）的</td><td>「<strong>若</strong>属皆且为所虏」——你们这些人</td></tr><tr><td>所</td><td>与动词组成&quot;所&quot;字结构，表&quot;……的事物&quot;</td><td>「道之<strong>所</strong>存，师之所存也」</td></tr><tr><td>为</td><td>做、作为、被、因为、替</td><td>「身死国灭，<strong>为</strong>天下笑」——被</td></tr><tr><td>焉</td><td>兼词（于之）、代词、语气词、形容词词尾</td><td>「积土成山，风雨兴<strong>焉</strong>」——在那里</td></tr><tr><td>也</td><td>判断、陈述、疑问、停顿语气</td><td>「师者，所以传道受业解惑<strong>也</strong>」</td></tr><tr><td>以</td><td>用、凭、因为、来、以致、认为</td><td>「不<strong>以</strong>物喜，不以己悲」——因为</td></tr><tr><td>因</td><td>依靠、趁着、通过、于是</td><td>「<strong>因</strong>宾客至蔺相如门谢罪」——通过</td></tr><tr><td>于</td><td>在、从、到、向、比、被</td><td>「青，取之<strong>于</strong>蓝」——从</td></tr><tr><td>与</td><td>和、给、结交、赞许、通&quot;欤&quot;</td><td>「<strong>与</strong>嬴而不助五国也」——结交</td></tr><tr><td>则</td><td>就、却、就是、那么</td><td>「位卑<strong>则</strong>足羞」——就</td></tr><tr><td>者</td><td>代词（……的人/事）、判断句标志、提顿</td><td>「古之学<strong>者</strong>必有师」</td></tr><tr><td>之</td><td>代词、助词（的 / 取消句子独立性 / 提宾 / 定语后置标志）、动词（往）</td><td>「师道<strong>之</strong>不传也久矣」——取消独立性</td></tr></tbody></table><h2 id="三、四类特殊句式" tabindex="-1">三、四类特殊句式 <a class="header-anchor" href="#三、四类特殊句式" aria-label="Permalink to &quot;三、四类特殊句式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>句式</th><th>标志</th><th>例句与翻译</th></tr></thead><tbody><tr><td>判断句</td><td>……者……也、乃、则、为、即</td><td>「陈胜者，阳城人也」——陈胜是阳城人</td></tr><tr><td>被动句</td><td>于、为、为……所、见、被</td><td>「吾属今为之虏矣」——我们这些人要被他俘虏了</td></tr><tr><td>宾语前置</td><td>否定句代词宾语前置；疑问代词宾语前置；&quot;之&quot;&quot;是&quot;提宾</td><td>「古之人不余欺也」——古代的人没有欺骗我</td></tr><tr><td>定语后置</td><td>中心词 + 之 + 形容词；中心词 + 数量词</td><td>「蚓无爪牙之利」——蚯蚓没有锋利的爪牙</td></tr></tbody></table><h3 id="状语后置-介词结构后置" tabindex="-1">状语后置（介词结构后置） <a class="header-anchor" href="#状语后置-介词结构后置" aria-label="Permalink to &quot;状语后置（介词结构后置）&quot;">​</a></h3><p>&quot;于/以 + 宾语&quot;常放在动词之后，翻译时要提到动词前面： 「青，取之于蓝，而青于蓝」→ 靛青，是从蓝草里提取出来的，可是比蓝草更蓝。</p><h2 id="四、翻译六字诀" tabindex="-1">四、翻译六字诀 <a class="header-anchor" href="#四、翻译六字诀" aria-label="Permalink to &quot;四、翻译六字诀&quot;">​</a></h2><p><strong>留、删、补、换、调、贯</strong>：</p><ol><li><strong>留</strong>：国名、地名、人名、官名、年号等专有名词保留；</li><li><strong>删</strong>：无实在意义的虚词（发语词、凑足音节的助词）直接删去；</li><li><strong>补</strong>：补出省略的主语、谓语、宾语、介词；</li><li><strong>换</strong>：古今异义词换成现代汉语，单音节词换成双音节词；</li><li><strong>调</strong>：调整特殊句式的语序；</li><li><strong>贯</strong>：根据上下文把语气、情感贯通成通顺的现代汉语。</li></ol><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ul><li>见到&quot;所以&quot;就翻译为因果连词：文言中&quot;所以&quot;常表&quot;用来……的（方法）&quot;；</li><li>把&quot;无论&quot;当作连词：文言中是&quot;不要说&quot;；</li><li>以为&quot;之&quot;取消句子独立性后可以译出：它没有实在意义，不译。</li></ul><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2><ul><li>《古汉语常用字字典》（商务印书馆）</li><li>《高中文言文全解》</li></ul>',22)])])}const c=d(s,[["render",n]]);export{q as __pageData,c as default};
